  "tour.start.t": "Emberwick in two minutes",
  "tour.start.b": "A medieval village where every coin is a NEAR token, AI craftsmen run their own shops, land deeds are NFTs, and the exchange quotes real cross-chain swaps through NEAR Intents. Press Start, then Next at each step. Join the village first if you have not (type a name, pick a path).",
  "tour.ai.t": "1 · Craftsmen who think with NEAR AI",
  "tour.ai.b": "In the shop panel on the right, the blue box shows today's plan from NEAR AI Cloud (stock up, discount, the reason). The plan's SHA-256 is written on NEAR every morning, and the model runs in a TEE: open the attestation report. Ask the baker something in the box; the answer appears over the characters.",
  "tour.haggle.t": "2 · Haggle (and ask for credit)",
  "tour.haggle.b": "At the inn, press 🤝 Haggle next to a row and name your price. The village rules decide (accept, counter, special offer or offence), NEAR AI says it in character, and nothing trades until you confirm. Broke and hungry? Ask the baker or innkeeper for food on credit.",
  "tour.token.t": "3 · A real token economy on NEAR",
  "tour.token.b": "EMWK is a NEP-141 token with a fixed supply of 25,000. Every shop, the treasury and the bank have their own NEAR accounts, and trades settle as batched transfers. The treasury card shows where the money came from; the links open the accounts on NearBlocks.",
  "tour.land.t": "4 · Land deeds that do something (NFT)",
  "tour.land.b": "Every plot is a NEP-171 NFT. A deed lets you build a house, sleep at home, rent it out for income and vote; deeds are bought and sold here in the land market and at the exchange.",
  "tour.intents.t": "5 · NEAR Intents at the exchange",
  "tour.intents.b": "The Exchange quarter asks the NEAR Intents 1Click API for live quotes: swap NEAR to USDC, BTC, ETH or SOL, or pay for land from another chain (a dry run: nothing is sent). The live NEAR price is an oracle that scales what travellers pay in the village.",
  "tour.council.t": "6 · The village DAO",
  "tour.council.b": "Players and AI villagers propose and vote (tax, watchtowers, setting part of the treasury aside in USDC or BTC with a live NEAR Intents quote). Every decision is recorded on NEAR with a memo.",
  "tour.week.t": "7 · Watch the economy run",
  "tour.week.b": "Press ⏩ 1 week in the top bar: a week of village life runs in about a minute with nobody touching prices, then a summary shows how prices moved, which craftsmen won or lost, and what the council decided.",
  "tour.end.t": "Thank you!",
  "tour.end.b": "The code is open on GitHub; the README lists every NEAR account and how to run it. Built at NEAR HACKATHON.",
