  "tour.done": "Bitti",
  "tour.start.t": "İki dakikada Emberwick",
  "tour.start.b": "Her paranın bir NEAR token'ı olduğu, yapay zekâlı ustaların kendi dükkânlarını işlettiği, arsa tapularının NFT olduğu ve borsanın NEAR Intents ile gerçek zincirler arası teklif aldığı bir ortaçağ köyü. Başla'ya, sonra her adımda İleri'ye bas. Henüz katılmadıysan önce köye katıl (isim yaz, yol seç).",
  "tour.ai.t": "1 · NEAR AI ile düşünen ustalar",
  "tour.ai.b": "Sağdaki dükkân panelinde mavi kutu NEAR AI Cloud'dan gelen bugünkü planı gösteriyor (stok artır, indirim yap, nedeni). Planın SHA-256 özeti her sabah NEAR'a yazılıyor ve model TEE içinde çalışıyor: doğrulama raporunu aç. Fırıncıya kutudan bir şey sor; cevap karakterlerin üstünde çıkar.",
  "tour.haggle.t": "2 · Pazarlık (ve veresiye)",
  "tour.haggle.b": "Handa bir satırın yanındaki 🤝 Pazarlık'a bas ve fiyatını söyle. Kararı köy kuralları verir (kabul, karşı teklif, özel teklif ya da kırgınlık), NEAR AI bunu karakteriyle söyler ve sen onaylamadan hiçbir şey el değiştirmez. Paran yok ve açsan fırıncıdan ya da hancıdan veresiye iste.",
  "tour.token.t": "3 · NEAR üzerinde gerçek bir token ekonomisi",
  "tour.token.b": "EMWK, 25.000 sabit arzlı bir NEP-141 token. Her dükkânın, hazinenin ve bankanın kendi NEAR hesabı var; alışverişler toplu transferlerle zincire geçiyor. Hazine kartı paranın nereden geldiğini gösterir; bağlantılar hesapları NearBlocks'ta açar.",
  "tour.land.t": "4 · İşe yarayan arsa tapuları (NFT)",
  "tour.land.b": "Her arsa bir NEP-171 NFT. Tapu ev kurmanı, evinde uyumanı, kiraya verip gelir almanı ve oy vermeni sağlar; tapular burada, arsa pazarında ve borsada alınıp satılır.",
  "tour.intents.t": "5 · Borsada NEAR Intents",
  "tour.intents.b": "Borsa mahallesi NEAR Intents 1Click API'den canlı teklif alıyor: NEAR'ı USDC, BTC, ETH ya da SOL'a çevir veya arsayı başka bir zincirden öde (deneme: hiçbir şey gönderilmez). Canlı NEAR fiyatı, köyde yolcuların ödediğini değiştiren bir oracle.",
  "tour.council.t": "6 · Köyün DAO'su",
  "tour.council.b": "Oyuncular ve yapay zekâlı köylüler öneri verip oy kullanıyor (vergi, gözcü kulesi, hazinenin bir kısmını canlı NEAR Intents teklifiyle USDC ya da BTC olarak ayırmak). Her karar NEAR'a not ile yazılıyor.",
  "tour.week.t": "7 · Ekonomiyi izle",
  "tour.week.b": "Üst çubukta ⏩ 1 hafta'ya bas: köyün bir haftası, fiyatlara kimse dokunmadan yaklaşık bir dakikada geçer; sonra fiyatların nasıl değiştiğini, hangi ustaların kazanıp kaybettiğini ve meclisin kararlarını gösteren bir özet çıkar.",
  "tour.end.t": "Teşekkürler!",
  "tour.end.b": "Kod GitHub'da açık; README bütün NEAR hesaplarını ve nasıl çalıştırılacağını listeliyor. NEAR HACKATHON'da yapıldı.",
