  "talk.miner.0": "铁匠多兰现在每份矿石出 {p} EMWK。",
  "talk.miner.1": "矿井里又冷又黑。不过工钱不错。",
  "talk.miner.1d": "山顶冒烟了！铁匠每块矿石都要拿去打剑。",
  "talk.miner.2": "哪里价高就在哪里卖。价格一整天都在变。",
